const E=Engine,$=s=>document.querySelector(s),money=n=>'₹'+Math.round(n).toLocaleString('en-IN'),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={...E.defaults},records=[];try{state={...state,...JSON.parse(localStorage.getItem('clarity-state')||'{}')};records=JSON.parse(localStorage.getItem('clarity-records')||'[]')}catch{}
const tabs=[['overview','Overview','◫'],['client','Client needs','♧'],['products','Product rules','▤'],['scenarios','Scenarios','⌁'],['history','Historical replay','↶'],['compare','Compare & suitability','⇄'],['report','Decision & report','▧'],['client-view','Client dashboard','♧']];const names={protected:'Capped growth note',deposit:'Fixed-return deposit',equity:'Market participation'};let tab='overview';
function persist(){try{localStorage.setItem('clarity-state',JSON.stringify(state))}catch{toast('Storage unavailable. Download a report to keep your work.')}}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2600)}function go(t){location.hash=t}function title(k,h,p,action=''){return `<div class="title-row"><div><div class="eyebrow">${k}</div><h1>${h}</h1><p class="sub">${p}</p></div>${action}</div>`}function btn(t,to,primary=true){return `<button class="btn ${primary?'primary':''}" data-go="${to}">${t}<span>↗</span></button>`}function card(label,value,meta){return `<div class="card"><div class="label">${label}</div><div class="value">${value}</div><div class="meta">${meta}</div></div>`}function badge(ok){return `<span class="tag ${ok?'':'warn'}">${ok?'Meets model rules':'Needs review'}</span>`}function field(key,label,type='number',min=0,max=10000000,step=1){return `<label class="field">${label}<input name="${key}" type="${type}" value="${esc(state[key])}" ${type==='number'?`min="${min}" max="${max}" step="${step}"`:''} required></label>`}
function chart(lines,opts={}){const w=700,h=260,left=62,right=24,top=22,bottom=36;const vals=lines.flatMap(l=>l.points.map(p=>p[1]));if(opts.target)vals.push(opts.target);let lo=Math.min(...vals)*.85,hi=Math.max(...vals)*1.08;if(hi===lo)hi=lo+1;const xs=lines.flatMap(l=>l.points.map(p=>p[0])),xmin=Math.min(...xs),xmax=Math.max(...xs);const X=x=>left+(x-xmin)/(xmax-xmin||1)*(w-left-right),Y=y=>h-bottom-(y-lo)/(hi-lo)*(h-top-bottom);let out=`<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${opts.label||'Investment outcomes chart'}">`;for(let i=0;i<4;i++){let val=lo+(hi-lo)*i/3;out+=`<line x1="${left}" y1="${Y(val)}" x2="${w-right}" y2="${Y(val)}" stroke="#edf0eb"/><text x="${left-12}" y="${Y(val)+3}" text-anchor="end" fill="#96a097" font-size="9">${opts.percent?val.toFixed(0)+'%':'₹'+(val/1000).toFixed(0)+'k'}</text>`}if(opts.target)out+=`<line x1="${left}" y1="${Y(opts.target)}" x2="${w-right}" y2="${Y(opts.target)}" stroke="#bac4b6" stroke-dasharray="4 5"/><text x="${w-right}" y="${Y(opts.target)-7}" text-anchor="end" fill="#98a58e" font-size="9">Goal ${money(opts.target)}</text>`;for(const l of lines){out+=`<path d="${l.points.map((p,i)=>(i?'L':'M')+X(p[0])+','+Y(p[1])).join(' ')}" fill="none" stroke="${l.color}" stroke-width="2.5" stroke-linejoin="round"/>`;for(const p of l.points)out+=`<circle cx="${X(p[0])}" cy="${Y(p[1])}" r="3.3" fill="white" stroke="${l.color}" stroke-width="2"><title>${opts.xLabel?opts.xLabel(p[0]):p[0]}: ${opts.percent?p[1].toFixed(1)+'%':money(p[1])}</title></circle>`}for(const x of [...new Set(xs)].filter((_,i,a)=>a.length<12||i%10===0))out+=`<text x="${X(x)}" y="${h-12}" text-anchor="middle" fill="#96a097" font-size="9">${opts.xLabel?opts.xLabel(x):x}</text>`;return out+'</svg>'}
function payoffChart(){return chart([{color:'#3b7f5e',points:Array.from({length:21},(_,i)=>{let r=-100+i*10;return [r,E.payoff(state,r)]})}],{target:state.target,xLabel:x=>x+'%',label:'Maturity payout against total market return'})}function checksHTML(p=state.product){return E.checks(state,p).map(c=>`<div class="check"><span class="status-icon ${c.ok?'':'fail'}">${c.ok?'✓':'!'}</span><div><h3>${c.name}</h3><p class="small">${esc(c.detail)}</p></div></div>`).join('')}
function overview(){let value=E.payoff(state,state.up),ratio=Math.min(100,value/state.target*100),ok=E.checks(state).every(c=>c.ok);return title('A CLEARER PICTURE','Good decisions start with clarity.','One goal. A few possibilities. A conversation that makes sense.',btn('Explore scenarios','scenarios'))+`<div class="cards">${card('Investment amount',money(state.amount),'One-time investment')}${card('Target amount',money(state.target),esc(state.goal))}${card('Time to goal',state.years+' years','Your planning horizon')}${card('Loss comfort',state.loss+'%','Maximum acceptable loss')}</div><div class="grid"><section class="panel"><div class="panel-head"><div><h2>What could your money become?</h2><p class="sub">${names[state.product]} · At maturity in ${state.term} years</p></div><span class="tag">ILLUSTRATIVE</span></div>${payoffChart()}<div class="between"><div class="legend"><span><i style="background:#3b7f5e"></i>Maturity payout</span><span><i style="background:#bac4b6"></i>Education target</span></div><span class="small">Total market change →</span></div></section><section class="panel"><div class="panel-head"><h2>A fit for the goal?</h2>${badge(ok)}</div><div class="goal-circle" style="--progress:${ratio}%"><div><strong>${ratio.toFixed(0)}<span style="font-size:15px">%</span></strong><div class="small">of target in upside case</div></div></div><div class="between row"><span>Upside outcome</span><strong>${money(value)}</strong></div><div class="between row"><span>Target gap</span><strong class="text-amber">${money(Math.max(0,state.target-value))}</strong></div><div class="info" style="margin-top:15px">${ok?'Meets the model’s essential rules. Outcomes and issuer risk still need a discussion.':'This option needs a closer look. Review the target, loss capacity, and timing together.'}</div></section></div><h2 class="section-label">Your next steps</h2><div class="journey"><button data-go="client"><span class="step">01 / UNDERSTAND</span><h3>Start with the person <b>↗</b></h3><p>Confirm the goal and what matters.</p></button><button data-go="compare"><span class="step">02 / EVALUATE</span><h3>Find the right fit <b>↗</b></h3><p>Put the alternatives side by side.</p></button><button data-go="report"><span class="step">03 / DOCUMENT</span><h3>Make the decision clear <b>↗</b></h3><p>Review, record, and take it with you.</p></button></div>`}
function client(){return title('01 / UNDERSTAND','Every investment starts with a person.','Capture what this money needs to do.')+`<div class="grid"><form class="panel" id="client-form"><div class="panel-head"><h2>Client & goal</h2><span class="tag">EDITABLE</span></div><div class="form-grid">${field('client','Client name','text')}${field('goal','What is the money for?','text')}${field('amount','Investment amount (₹)','number',1)}${field('target','Target amount (₹)','number',1)}${field('years','Time to goal (years)','number',1,10)}${field('loss','Maximum acceptable loss (%)','number',0,100)}<label class="field full">Will the client need early access?<select name="liquidity"><option value="no" ${state.liquidity==='no'?'selected':''}>No — can hold until maturity</option><option value="yes" ${state.liquidity==='yes'?'selected':''}>Yes — access to money is essential</option></select></label></div><div class="actions"><button class="btn primary">Save & select a product ↗</button></div></form><div><section class="panel"><h2>The goal at a glance</h2><div class="row between"><span>Required growth</span><strong>${((state.target/state.amount-1)*100).toFixed(1)}%</strong></div><div class="row between"><span>Required annual return</span><strong>${((Math.pow(state.target/state.amount,1/state.years)-1)*100).toFixed(2)}%</strong></div><div class="row between"><span>Loss comfort in rupees</span><strong>${money(state.amount*state.loss/100)}</strong></div><p class="small" style="margin-top:15px">The target is the amount needed at the goal date. These figures do not include taxes or inflation.</p></section><div class="info">A higher desired return does not imply a higher ability to bear loss.</div></div></div>`}
function products(){return title('02 / CONFIGURE','Choose the rules. See the possibilities.','Three example structures. All terms are editable.')+`<div class="product-grid">${[['protected','◇','Limited upside. A maturity floor.','Capped return'],['deposit','▥','A fixed rate, compounded annually.','Predictable formula'],['equity','⌁','Full participation in market moves.','Capital at risk']].map(([id,icon,desc,tag])=>`<button class="product ${state.product===id?'selected':''}" data-product="${id}"><span class="symbol">${icon}</span><h2>${names[id]}</h2><p>${desc}</p><span class="tag">${state.product===id?'✓ Selected':tag}</span></button>`).join('')}</div><div class="grid"><form id="product-form" class="panel"><div class="panel-head"><h2>${names[state.product]} terms</h2><span class="tag">EXAMPLE PRODUCT</span></div><div class="form-grid">${field('term','Holding period (years)','number',1,10)}${field('fee','One-time fee (% of principal)','number',0,20,.1)}${state.product==='deposit'?field('rate','Annual compound rate (%)','number',0,30,.1):state.product==='protected'?field('cap','Total return cap (%)','number',0,100,.1)+field('participation','Market participation (%)','number',0,200,1)+field('floor','Principal floor at maturity (%)','number',0,100,1):''}</div><div class="actions"><button class="btn primary">Apply rules & simulate ↗</button></div></form><section class="panel"><h2>How the payout works</h2><p class="sub">${state.product==='protected'?'Principal × [1 + max(floor − 100%, min(cap, market return × participation))], less the fee.':state.product==='deposit'?'Principal × (1 + annual rate) ^ holding period, less the fee.':'Principal × (1 + total market return), less the fee; payout cannot go below zero.'}</p><div class="info" style="margin-top:24px">${state.product==='equity'?'Redeemable at market value; capital can be lost.':'Held to maturity in this model. Early withdrawal is not modelled.'} Floor and fixed payouts assume the issuer pays. Fees reduce any floor. Taxes are excluded.</div></section></div>`}
function productScenarios(){return title('03 / EXPLORE','What happens to '+money(state.amount)+'?','Change the market outcome. The product rules do the rest.',btn('Replay the past','history',false))+`<div class="scenario-cards">${[['up','Market rises','#4f8967'],['flat','Market stays flat','#a2b795'],['down','Market falls','#c19a61']].map(([key,label,c])=>`<div class="card" style="--accent:${c}"><div class="between"><div class="label">${label}</div><span class="tag">${state[key]>0?'+':''}${state[key]}%</span></div><div class="value">${money(E.payoff(state,state[key]))}</div><div class="meta">${E.payoff(state,state[key])>=state.amount?'+':''}${money(E.payoff(state,state[key])-state.amount)} net change</div><input aria-label="${label} total return" data-range="${key}" type="range" min="${key==='down'?-100:key==='flat'?-10:0}" max="${key==='down'?0:key==='flat'?10:100}" value="${state[key]}" style="width:100%;margin-top:24px"></div>`).join('')}</div><section class="panel"><div class="panel-head"><div><h2>The full range of possibilities</h2><p class="sub">${names[state.product]} · Total return over ${state.term} years</p></div><span class="tag">MATURITY PAYOUT</span></div>${dynamicProductChartHTML()}<div class="small" style="text-align:center">Underlying market change over the holding period</div></section><div class="info">These are conditional calculations, not forecasts or probabilities. The curve shows the payout at maturity, not an interim investment value.</div>`}
function history(){const points=E.replay(state),end=state.start+state.term-1;return title('04 / LOOK BACK','A real market. A hypothetical investment.','Replay the same rules against historical Nifty 50 total returns.')+`<section class="panel"><div class="panel-head"><div><h2>Select a historical window</h2><p class="sub">${state.term} complete calendar years · Annual observations</p></div><label class="field">Start year<select id="history-year">${Object.keys(E.returns).filter(y=>+y+state.term-1<=2022).map(y=>`<option ${+y===state.start?'selected':''}>${y}</option>`).join('')}</select></label></div>${points?chart([{color:'#5a8a6a',points:points.map(p=>[p.year,p.index])}],{percent:true,label:'Historical cumulative Nifty 50 total return'}):'<p class="notice">Choose a start year with enough historical observations.</p>'}</section>${points?`<div class="cards">${card('Historical period',state.start+'–'+end,'Start of first year to end of last')}${card('Market total return',points.at(-1).index.toFixed(1)+'%','Compounded annual observations')}${card('Hypothetical payout',money(points.at(-1).value),names[state.product])}${card('Gap to current target',money(Math.max(0,state.target-points.at(-1).value)),'Same principal and product rules')}</div><section class="panel"><h2>Annual observations</h2><div class="table-wrap"><table><thead><tr><th>Calendar year</th><th>Nifty 50 TR return</th><th>Cumulative return</th></tr></thead><tbody>${points.slice(1).map(p=>`<tr><td>${p.year}</td><td>${E.returns[p.year].toFixed(1)}%</td><td>${p.index.toFixed(1)}%</td></tr>`).join('')}</tbody></table></div></section>`:''}<div class="info">Source: <a href="https://niftyindices.com/docs/default-source/indices/nifty-50/nifty-50-at-20k.pdf?sfvrsn=54a79334_12" target="_blank" rel="noopener">NSE Indices · Nifty 50 at 20,000</a>. Published annual total returns, rounded to one decimal. Dividends included in the underlying index; no daily drawdown estimate. Product payouts are hypothetical and calculated only at maturity. Past performance does not predict future results.</div>`}
function compare(){let pass=Object.keys(names).filter(p=>E.checks(state,p).every(c=>c.ok));return title('05 / EVALUATE','An attractive option should also fit.','Same money. Same holding period. A clearer comparison.')+`<div class="notice">${pass.length?pass.length+' option(s) meet the model’s essential rules. This is a screening result, not a recommendation.':'No option meets all essential requirements. Revise the terms or record “no suitable product”.'}</div><section class="panel table-wrap"><table><thead><tr><th>EXAMPLE PRODUCT</th><th>FALL ${state.down}%</th><th>FLAT ${state.flat}%</th><th>RISE +${state.up}%</th><th>MODEL CHECK</th><th></th></tr></thead><tbody>${Object.keys(names).map(p=>`<tr><td><strong>${names[p]}</strong>${p===state.product?'<div class="small">Selected product</div>':''}</td><td>${money(E.payoff(state,state.down,p))}</td><td>${money(E.payoff(state,state.flat,p))}</td><td>${money(E.payoff(state,state.up,p))}</td><td>${badge(pass.includes(p))}</td><td><button class="btn" data-product="${p}">Review</button></td></tr>`).join('')}</tbody></table></section><div class="grid"><section class="panel"><div class="panel-head"><h2>${names[state.product]}</h2>${badge(pass.includes(state.product))}</div><div class="checks">${checksHTML()}</div><div class="actions">${btn('Revise product','products',false)}${btn('Review decision','report')}</div></section><section class="panel"><h2>What each option gives up</h2><div class="row"><strong>Capped growth note</strong><p class="small">Upside above the cap, early access, and issuer certainty.</p></div><div class="row"><strong>Fixed-return deposit</strong><p class="small">Market upside and early access in this model.</p></div><div class="row"><strong>Market participation</strong><p class="small">Capital certainty. The entire principal is exposed.</p></div><p class="small" style="margin-top:18px">Loss checks use the contractual model at a −100% market return. Issuer default is outside the calculation. A feasible target is not a guaranteed target.</p></section></div>`}
function report(){let ok=E.checks(state).every(c=>c.ok);return title('06 / RECORD','A considered decision. Clearly documented.','Review the explanation with the client, then save a snapshot.')+`${clientReviewHTML()}<div class="grid"><form id="report-form" class="panel"><div class="panel-head"><h2>Client understanding & RM review</h2>${badge(ok)}</div><div class="info">For ${esc(state.client)}, ${money(state.amount)} is intended to become ${money(state.target)} in ${state.years} years. Under ${names[state.product].toLowerCase()} rules, the selected scenarios produce ${money(E.payoff(state,state.down))} to ${money(E.payoff(state,state.up))}. ${ok?'This option meets the model’s checks; returns remain conditional.':'This option fails one or more essential checks and cannot be recorded as suitable.'}</div><label class="field" style="margin-top:24px">Decision<select name="decision"><option value="revise">Revise requirements or product</option><option value="none">No suitable product</option>${ok?'<option value="proceed">Proceed with selected option after review</option>':''}</select></label><label class="field" style="margin-top:20px">Reason for the decision<textarea name="reason" rows="3" required minlength="10" placeholder="Record the key trade-off and next step…"></textarea></label><div class="checks" style="margin-top:22px"><label class="check"><input type="checkbox" required>Client understands the potential loss, cap, fees, and access restrictions.</label><label class="check"><input type="checkbox" required>RM reviewed the assumptions; past returns are not a promise.</label></div><div class="actions"><button class="btn primary">Save decision ↓</button><button type="button" class="btn" id="print">Print / PDF</button></div></form><section class="panel"><h2>Decision history</h2><p class="sub">Snapshots stored in this browser.</p>${records.length?records.map((r,i)=>`<div class="row"><div class="between"><strong>${esc(r.client)}</strong><span class="small">${new Date(r.date).toLocaleDateString('en-IN')}</span></div><p class="small">${esc(r.decisionLabel)}</p><button class="btn" data-download="${i}" style="margin-top:10px">Download report ↓</button></div>`).join(''):'<div class="empty">No saved decisions yet.</div>'}</section></div>`}
function render(){tab=location.hash.slice(1)||'overview';if(tab==='client-view'){renderClient();return}document.body.classList.remove('client-mode');$('.avatar').textContent='RM';$('.workspace').textContent='RELATIONSHIP MANAGER WORKSPACE';if(!tabs.some(t=>t[0]===tab))tab='overview';$('#nav').innerHTML=tabs.map(([id,name,icon],i)=>`<a href="#${id}" class="${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${name}<span class="nav-n">0${i}</span></a>`).join('');$('#breadcrumb').textContent=tabs.find(t=>t[0]===tab)[1];$('#app').innerHTML=({overview,client,products,scenarios,history,compare,report}[tab])();bind()}
function formSave(form,next){form?.addEventListener('submit',e=>{e.preventDefault();for(const [k,v] of new FormData(form))state[k]=typeof E.defaults[k]==='number'?Number(v):v;if(state.start+state.term-1>2022)state.start=2023-state.term;persist();toast('Changes saved');go(next)})}
function bind(){bindMath();document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>{state.product=b.dataset.product;persist();render()});formSave($('#client-form'),'products');formSave($('#product-form'),'scenarios');document.querySelectorAll('[data-range]').forEach(r=>r.oninput=()=>{state[r.dataset.range]=+r.value;persist();const box=r.closest('.card');box.querySelector('.tag').textContent=(+r.value>0?'+':'')+r.value+'%';box.querySelector('.value').textContent=money(E.payoff(state,+r.value));box.querySelector('.meta').textContent=(E.payoff(state,+r.value)>=state.amount?'+':'')+money(E.payoff(state,+r.value)-state.amount)+' net change';const chartBox=document.querySelector('#product-payoff-chart');if(chartBox)chartBox.innerHTML=dynamicProductChart()});if($('#history-year'))$('#history-year').onchange=e=>{state.start=+e.target.value;persist();render()};if($('#print'))$('#print').onclick=()=>window.print();document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>download(records[+b.dataset.download]));$('#report-form')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target),decision=f.get('decision'),labels={revise:'Revise requirements or product',none:'No suitable product',proceed:'Proceed after review'};let r={date:new Date().toISOString(),client:state.client,decision,decisionLabel:labels[decision],reason:f.get('reason'),clientPreference:currentPreference(),inputs:{...state},checks:E.checks(state),comparisons:Object.keys(names).map(p=>({product:names[p],down:E.payoff(state,state.down,p),flat:E.payoff(state,state.flat,p),up:E.payoff(state,state.up,p),checks:E.checks(state,p)})),replay:E.replay(state),acknowledgments:['Client understanding confirmed','RM review completed']};records.unshift(r);try{localStorage.setItem('clarity-records',JSON.stringify(records));toast('Decision snapshot saved')}catch{toast('Storage unavailable; report downloaded');download(r)}render()})}
function download(r){let s=r.inputs;let text=`CLARITY — INVESTMENT DECISION REPORT\n${new Date(r.date).toLocaleString('en-IN')}\n\nClient: ${r.client}\nGoal: ${s.goal}\nInvestment: ${money(s.amount)}\nTarget: ${money(s.target)}\nHorizon: ${s.years} years\nLoss capacity: ${s.loss}%\nEarly access needed: ${s.liquidity}\n\nDECISION: ${r.decisionLabel}\nReason: ${r.reason}\n\nCLIENT PREFERENCE\n${r.clientPreference?JSON.stringify(r.clientPreference,null,2):'Not recorded'}\n\nPRODUCT: ${names[s.product]}\n${JSON.stringify(s,null,2)}\n\nSUITABILITY\n${r.checks.map(c=>(c.ok?'PASS':'REVIEW')+' — '+c.name+': '+c.detail).join('\n')}\n\nALTERNATIVES (down / flat / up)\n${r.comparisons.map(c=>c.product+': '+[c.down,c.flat,c.up].map(money).join(' / ')+'\n'+c.checks.map(x=>x.name+': '+(x.ok?'pass':'review')).join('; ')).join('\n')}\n\nHISTORICAL REPLAY\n${JSON.stringify(r.replay,null,2)}\nSource: NSE Indices, Nifty 50 at 20,000; annual TR returns rounded to one decimal.\nhttps://niftyindices.com/docs/default-source/indices/nifty-50/nifty-50-at-20k.pdf?sfvrsn=54a79334_12\n\nClient understanding and RM review confirmed.\nIllustrative product rules; not a product offer or investment advice. Before tax; fee deducted once from principal at maturity. No issuer default modelling. Historical results do not predict future returns. No early exit model for deposit/note.\n`;let url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download='clarity-decision-'+r.date.slice(0,10)+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
window.addEventListener('hashchange',render);render();
